layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 3px double var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: ChicagoFLF; font-weight: 700; font-style: normal; line-height: 1.175; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 4px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: "Roboto Mono", SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace, ChicagoFLF, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: 10%; text-underline-offset: 25%; transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out, text-decoration 0.2s ease-in-out, box-shadow 0.2s ease-in-out }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: ChicagoFLF; font-size: 28.8px; font-weight: 700; font-style: normal; line-height: 1.175; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 25%; transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out, text-decoration 0.2s ease-in-out, box-shadow 0.2s ease-in-out }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: "Roboto Mono", SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace, ChicagoFLF, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: 10%; text-underline-offset: 25%; transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out, text-decoration 0.2s ease-in-out, box-shadow 0.2s ease-in-out }
[data-ryt="rec-card"] [data-ryt="title"]:hover { opacity: 1 }
body:hover { opacity: 1 }
[data-ryt="brand"]:hover { opacity: 1 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { opacity: 1 }
[data-ryt="section"] > h2:hover { opacity: 1 }
[data-ryt="footer"]:hover { opacity: 1 }
